def is_anagram(s1, s2):
    # Strip the strings of white space and convert to lower case
    s1 = s1.replace(" ", "").lower()
    s2 = s2.replace(" ", "").lower()

    if len(s1) != len(s2):
        return False

    # Count the number of each character in the string
    count = {}
    for char in s1:
        if char not in count:
            count[char] = 1
        else:
            count[char] += 1

    # Check if the characters present in s2 too
    for char in s2:
        if char not in count:
            return False
        if count[char] == 0:
            return False
        count[char] -= 1

    return True

