The Factory pattern centralizes object creation:

```python
class Notification:
    def send(self, message: str) -> str: pass

class EmailNotification(Notification):
    def send(self, message: str) -> str:
        return f"Sending Email: {message}"

class SMSNotification(Notification):
    def send(self, message: str) -> str:
        return f"Sending SMS: {message}"

class NotificationFactory:
    _registry = {
        "email": EmailNotification,
        "sms": SMSNotification
    }

    @classmethod
    def create(cls, channel: str) -> Notification:
        if channel not in cls._registry:
            raise ValueError(f"Unknown notification channel: {channel}")
        return cls._registry[channel]()

service = NotificationFactory.create("email")
print(service.send("Account created!"))
