import enum

class State(enum.Enum):
    Initialize = 0,
    Event1 = 1,
    Event2 = 2,
    Event3 = 3,
    Finalize = 4

class StateMachine:
    def __init__(self):
        self.state = State.Initialize

    def process(self):
        if self.state == State.Initialize:
            self.state = State.Event1
        elif self.state == State.Event1:
            self.state = State.Event2
        elif self.state == State.Event2:
            self.state = State.Event3
        elif self.state == State.Event3:
            self.state = State.Finalize
        elif self.state == State.Finalize:
            self.state = State.Initialize

To create a container or data structure that preserves type parameterization, inherit from `typing.Generic[T]`:

```python
from typing import TypeVar, Generic, List

T = TypeVar("T")

class Stack(Generic[T]):
    def __init__(self) -> None:
        self._items: List[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        return self._items.pop()

    def is_empty(self) -> bool:
        return len(self._items) == 0

# Instantiation with explicit type
int_stack: Stack[int] = Stack()
int_stack.push(10)
int_stack.push(20)
print(int_stack.pop())  # 20
